def preg(id,title,first,last,interval,summary,detail,source,**kw):
    add(id,title,0,120,interval,'Schwangerschaft',summary,detail,source,pregnancy=True,pregStartDay=first,pregEndDay=last,
        harm='Untersuchungen sind freiwillig. Der persönliche Plan der betreuenden Praxis und der Mutterpass haben Vorrang. Bei Beschwerden nicht auf dieses Zeitfenster warten.',**kw)
preg('pregvisit','Regelmäßige Schwangerschaftsvorsorge',0,294,'NONE','Zunächst etwa alle 4 Wochen, ab SSW 32 enger','Üblicherweise ab SSW 32 alle zwei Wochen; bei Risiken oder Terminüberschreitung individuell häufiger. Hebammen und ärztliche Praxis können die Betreuung abstimmen. Blutdruck, Gewicht, Urin, Entwicklung und Beschwerden gehören zur Betreuung.','pregschedule,pregnancy')
preg('preginitial','Erstuntersuchung & Mutterpass',0,294,'ONCE','Möglichst früh nach Feststellung','Anamnese, Beratung und erste Laboruntersuchungen: unter anderem Blutgruppe/Rhesusfaktor, Antikörpersuchtest und Hämoglobin. Infektionsscreenings auf Syphilis, Chlamydien und Hepatitis B sowie Angebot eines HIV-Tests; Rötelnimmunität nach vorhandenen Nachweisen klären. Nicht bis zur späten Schwangerschaft warten.','pregnancy,maternity')
preg('pregus1','1. Basis-Ultraschall',56,83,'ONCE','SSW 8+0 bis 11+6','Erstes reguläres Ultraschallfenster. Die Praxis prüft unter anderem Schwangerschaftssitz, Entwicklung und Schwangerschaftsalter.','maternity,pregscreen')
preg('pregus2','2. Basis-Ultraschall',126,153,'ONCE','SSW 18+0 bis 21+6','Wahl zwischen Basis- und erweitertem Basis-Ultraschall als Kassenleistung. Für die erweiterte Untersuchung ist eine entsprechende ärztliche Qualifikation nötig.','maternity,pregscreen')
preg('pregus3','3. Basis-Ultraschall',196,223,'ONCE','SSW 28+0 bis 31+6','Drittes reguläres Ultraschallfenster zur Beurteilung von Wachstum und Entwicklung. Zusätzliche medizinisch notwendige Kontrollen sind von diesem Screening getrennt.','maternity,pregscreen')
preg('pregglucose','Test auf Schwangerschaftsdiabetes',168,195,'ONCE','SSW 24+0 bis 27+6','Vortest mit 50 g Glukose; bei entsprechend auffälligem Ergebnis folgt ein diagnostischer 75-g-Test. Die Praxis erklärt Vorbereitung und Ablauf. Bestehender Diabetes benötigt einen eigenen Betreuungsplan.','maternity,pregnancy')
preg('pregantibody','Erneuter Antikörpersuchtest',161,188,'ONCE','SSW 23+0 bis 26+6','Erneute Suche nach Blutgruppen-Antikörpern bei allen Schwangeren, auch bei positivem Rhesusfaktor.','maternity')
preg('pregrh','Fetalen Rhesusfaktor besprechen',77,294,'NONE','Ab SSW 11+0 · bei RhD-negativer Mutter','Nichtinvasiver Test auf den kindlichen Rhesusfaktor kann eine unnötige Anti-D-Prophylaxe vermeiden. Keine Trisomie-Untersuchung. Eignung, Einwilligung und Beratung in der Praxis prüfen.','maternity,pregscreen',risk='pregRh',coverage='PREG_CONDITION')
preg('pregantid','Anti-D-Prophylaxe prüfen',189,209,'ONCE','SSW 27+0 bis 29+6 · nur bei Indikation','Bei RhD-negativer Mutter ohne Anti-D-Antikörper und RhD-positivem oder unbekanntem fetalem Status prüfen. Nicht nötig bei sicher RhD-negativem Fetus. Weitere Indikationen etwa nach Blutungen oder Geburt gehören in ärztliche Hände.','maternity',risk='pregRh',coverage='PREG_CONDITION')
preg('pregpertussis','Keuchhusten-Impfung besprechen',189,294,'ONCE','Ab der 28. SSW · in jeder Schwangerschaft','Im frühen dritten Trimenon empfohlen, unabhängig von früheren Pertussisimpfungen. Bei erhöhter Frühgeburtswahrscheinlichkeit schon im zweiten Trimenon. Das angezeigte Fenster dient der frühzeitigen Terminabsprache; die Praxis legt den geeigneten Impftermin fest.','pregvax',coverage='PREG_CONDITION')
preg('pregflu','Grippeimpfung in der Schwangerschaft',0,294,'NONE','Ab dem 2. Trimenon, bei Risiko schon früher','Saisonalen Impfschutz prüfen. Bei zusätzlichen Grunderkrankungen bereits im ersten Trimenon empfohlen. Keine zweite Impfung in derselben Saison allein wegen einer Schwangerschaft.','pregflu',coverage='PREG_CONDITION')
preg('pregnipt','NIPT: Beratung nach persönlichem Bedarf',0,294,'NONE','Keine Routine allein aufgrund des Alters','GKV-Leistung in begründeten persönlichen Situationen, wenn die Frage nach einer Trisomie entsteht und die Ungewissheit unzumutbar belastet. Qualifizierte Beratung und informierte Entscheidung notwendig. Ein auffälliges Ergebnis ist keine gesicherte Diagnose.','nipt',risk='pregNipt',coverage='PREG_CONDITION')
preg('pregtoxo','Toxoplasmose: Zusatztest einordnen',0,294,'NONE','Ohne Verdacht keine allgemeine Regelleistung','Nutzen und Folgen eines zusätzlichen Tests besprechen. Bei Infektionsverdacht andere Abrechnung. TK: ohne Verdacht selbst bezahlen; BARMER Familie Plus gemeinsames Budget; DAK MamaPLUS übernimmt den Test laut Leistungsseite.','pregtk,pregbarmer,pregdaktoxo',kind='EXTRA',coverage='PREG_EXTRA')
preg('preggbs','B-Streptokokken: Test besprechen',238,258,'NONE','Etwa 35.–37. Schwangerschaftswoche','Abstrich vor der Geburt kann das Vorgehen bei der Entbindung beeinflussen. Keine pauschale Regelleistung; Kosten und Indikation vorher prüfen. Nicht mit einer akuten Infektionsdiagnostik verwechseln.','pregdakgbs,pregbarmer',kind='EXTRA',coverage='PREG_EXTRA')

knowledge=[
('Fundiert','Die größte Wirkung liegt im Alltag','In jedem Erwachsenenalter: nicht rauchen, regelmäßig bewegen und Kraft erhalten, ausreichend schlafen, ausgewogen essen und soziale Kontakte pflegen. Blutdruck und individuelle Risiken beim Check-up ansprechen. Das sind alltagstaugliche Präventionsansätze, kein garantierter Lebensverlängerungsplan.',['aging']),
('Gezielt statt pauschal','Vitamine: kein Startalter für alle','Für gut versorgte gesunde Erwachsene gibt es keine allgemeine Pflicht zu Vitaminpräparaten. Vitamin D bei geringer Eigenbildung oder erhöhtem Risiko, B12 insbesondere bei veganer Ernährung oder Aufnahmestörungen gezielt klären. Alter allein begründet kein jährliches Vitaminpanel; nachgewiesenen Mangel gezielt behandeln.',['dge','dvit','b12']),
('Individuelle Behandlung','Hormone sind keine allgemeine Vorsorge','Wechseljahrsbeschwerden können eine individuell abgewogene Hormontherapie begründen. Sie ist kein allgemeines Anti-Aging-Programm; Nutzen und Risiken ärztlich besprechen. Keine automatische Testosteron-, Östrogen- oder Wachstumshormon-Empfehlung ab einem Geburtstag.',['hormones','aging']),
('Forschung','Rapamycin, Metformin, NAD & Co.','Forschung zu Alterungsprozessen ist interessant, begründet aber keinen Einnahmeplan für gesunde Menschen. Tierdaten und veränderte Biomarker beweisen keine längere gesunde Lebenszeit beim Menschen. Keine Selbstmedikation; für andere Erkrankungen verordnete Medikamente nicht eigenmächtig ändern.',['aging','fasting']),
('Kostenlücken','Mehr Tests sind nicht automatisch besser','Ganzkörper-MRT, routinemäßige Tumormarker, große Vitamin-/Hormonpanels und häufigere Screenings sind keine pauschalen altersbezogenen GKV-Vorsorgeleistungen. Bei Symptomen oder begründetem Verdacht kann dieselbe Untersuchung medizinisch angezeigt und abrechenbar sein. Vor Selbstzahlerleistungen Nutzen, Folgen und Preis klären.',['gcheck','psa']),
('Ausblick · Österreich','Ein anderer Check-up-Rhythmus','In Österreich gibt es für Menschen ab 18 mit Wohnsitz im Land einmal jährlich eine kostenlose Vorsorgeuntersuchung. Das ist ein anderes Versorgungsprogramm und kein Grund, in Deutschland alle Untersuchungen jährlich zu wiederholen.',['at']),
('Ausblick · England','NHS Health Check: 40 bis 74','In England erhalten geeignete Personen zwischen 40 und 74 ohne bestimmte Vorerkrankungen normalerweise alle fünf Jahre ein Angebot. Die Länderbeispiele sind Orientierung; der persönliche Plan in Morgenklar nutzt ausschließlich Deutschland.',['uk']),
('So liest du deinen Plan','Angebot, Fälligkeit und Empfehlung','Die App zeigt Vorsorgeangebote für Menschen ohne Beschwerden. Ein bezahltes Angebot ist keine Pflicht und nicht immer eine fachliche Empfehlung. Ohne dokumentierte Vorgeschichte heißt es „Termin prüfen“. Frühere Auffälligkeiten, Schwangerschaft, familiäre Risiken und Erkrankungen können einen anderen Plan erfordern.',['overview']),
]
